// 제너레이터 채움 — 진입점(onpageload)에서 순차 실행.
/**
 * @method
 * @name scwin.init_fillGen
 * @author Inswave
 * @date 2026. 09. 29
 * @param boxId
 * @returns
 * @hidden N
*/
scwin.init_fillGen = function (boxId) {
    // 채우지 못한 자리를 모은다(동작은 계속 — 화면은 종전과 같다).
    const genSkip = [];
    let genCleared = 0;
    const genFills = [{ genId: "c_foreach_50", entity: "dlt_briefList", countIds: [], cells: [{ childId: "btn_briefPopView", fn: function (v, i) { return String(v("briefPublNm")); } }] },
        { genId: "c_foreach_63", entity: "dlt_checkPointList", countIds: [], cells: [{ childId: "__rc0", fn: function (v, i) { return String(v("title")); } }, { childId: "btn_checkPointPopView", fn: function (v, i) { return String(v("contnContn")); } }] },
        { genId: "c_foreach_76", entity: "dlt_workExampleList", countIds: [], cells: [{ childId: "__rc1", fn: function (v, i) { return String(v("title")); } }, { childId: "btn_workExamplePopView", fn: function (v, i) { return String(v("contnContn")); } }] },
        { genId: "c_foreach_91", entity: "dlt_entityBbsAttachVO", countIds: [], cells: [{ childId: "btn_issueDataPopView", fn: function (v, i) { return String(v("attachFileNm")); } }] },
        { genId: "c_foreach_89", entity: "dlt_issueDataList", countIds: [], cells: [{ childId: "__rc2", fn: function (v, i) { return String(v("title")); } }] }];
    const gf = genFills;
    for (let g = 0; g < gf.length; g++) {
        const f = gf[g];
        if (boxId && f.entity !== boxId) { continue; }
        const gen = $c.util.getComponent(f.genId);
        const ds = $c.util.getComponent(f.entity);
        if (!gen || !ds || !ds.getTotalRow) { genSkip.push({ gen: f.genId, box: f.entity, why: !gen ? 'no-generator' : 'no-box' }); continue; }
        const n = ds.getTotalRow();
        if (!n) { genSkip.push({ gen: f.genId, box: f.entity, why: 'empty-box' }); continue; }
        // 멱등 — 이미 채워진 제너레이터는 건너뛴다(플래그 없이 컴포넌트 상태로 판단).
        //   단, 상자를 지정해 «다시 그리라» 고 부른 경우(데이터가 새로 담긴 때)는 비우고 다시 채운다.
        if (gen.getLength && gen.getLength() > 0) {
            if (!boxId) { continue; }
            const had = gen.getLength();
            while (gen.getLength() > 0) { gen.removeChild(); }
            genCleared += had;
        }
        let row = 0;
        const cell = function (col) { const v = ds.getCellData(row, col); return (v === undefined || v === null) ? '' : v; };
        for (let i = 0; i < n; i++) {
            row = i;
            gen.insertChild(i);
            for (let c = 0; c < f.cells.length; c++) {
                const ch = gen.getChild(i, f.cells[c].childId);
                if (!ch || !ch.setValue) { continue; }
                ch.setValue(f.cells[c].fn(cell, i));
            }
            for (let k = 0; k < f.countIds.length; k++) {
                const cn = gen.getChild(i, f.countIds[k]);
                if (cn && cn.setValue) { cn.setValue(String(i + 1)); }
            }
            // 행 조건 — 마지막 행에만 보이는 자리.
            if (f.rowConds) {
                for (let rc = 0; rc < f.rowConds.length; rc++) {
                    const rn = gen.getChild(i, f.rowConds[rc].childId);
                    if (!rn) { continue; }
                    const show = (f.rowConds[rc].kind === 'last') ? (i === n - 1) : true;
                    if (rn.setStyle) { rn.setStyle('display', show ? '' : 'none'); }
                }
            }
        }
    }
    if (genSkip.length) {
        // 우리 계측이 읽는 자리 — 화면 동작에는 영향이 없다.
        scwin.genFillSkipped = genSkip;
    }
    if (genCleared) { scwin.genFillCleared = (scwin.genFillCleared || 0) + genCleared; }
};

// [A] 초기 목록 미해결 — 진입 근거가 다른 액션을 가리킨다(search vs brief vs checkpoint vs workexample) — 어느 쪽인지 정할 근거가 없다


// 화면 전환 파라미터 수신 — 엔진 표준(§106). 진입 파라미터 전체를 컨텍스트 dataMap 에 담는다. onpageload 합성 단계.
/**
 * @method
 * @name scwin.init_recvParam
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

scwin.form_searchFrm = { action: "", method: 'post', target: '' };

// 화면 진입점 — 초기화 단계를 데이터 의존 순서로 호출한다.
/**
 * @method
 * @name scwin.onpageload
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        scwin.init_fillGen();
        await scwin.init_conds();
    } catch (e) {
        $c.exception.handleError(e, { context: 'jldfil45202.onpageload' });
    }
};


///////// 3. 컴포넌트 이벤트 영역 /////////

/**
 * @event
 * @name scwin.btn_searchFind_onclick
 * @author Inswave
 * @date 2026. 09. 29
 * @param e
 * @returns
 * @hidden N
*/
scwin.btn_searchFind_onclick = async function(e){
    try {
        const ev = e;
        const event = ev;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        /* sdd-asis-lifecycle:begin btn_searchFind_onclick — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        await scwin.searchFind()
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil45202.btn_searchFind_onclick' }); }
};

/**
 * @event
 * @name scwin.btn_searchFindDetail_onclick
 * @author Inswave
 * @date 2026. 09. 29
 * @param e
 * @returns
 * @hidden N
*/
scwin.btn_searchFindDetail_onclick = async function(e){
    try {
        const ev = e;
